package ru.truetv.launcher;
import android.app.*;import android.content.*;import android.net.*;import android.os.*;import java.io.*;import java.net.*;import java.util.*;import ru.truetv.bridge.*;import ru.truetv.bridge.android.*;
/** Actual SDK28 VpnService drops the default route; physical-network sockets must still send. */
public final class LanVpnCheck extends Instrumentation {
 private Bundle args;private StringBuilder log=new StringBuilder();private int checks;
 public void onCreate(Bundle b){args=b;super.onCreate(b);start();}private void check(boolean ok,String msg){log.append(ok?"PASS ":"FAIL ").append(msg).append('\n');checks++;if(!ok)throw new AssertionError(msg);}private void shell(String s)throws Exception{try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand(s))){byte[] b=new byte[1024];while(in.read(b)!=-1){}}}
 public void onStart(){Bundle result=new Bundle();try{Context c=getTargetContext();if(!Build.FINGERPRINT.contains("generic")&&!Build.MODEL.contains("Android SDK"))throw new AssertionError("VM only");boolean allowed=!"deny".equals(args.getString("policy"));int port=Integer.parseInt(args.getString("port"));String pin=args.getString("pin");InetAddress host=InetAddress.getByName("10.0.2.2");Identity phone=Identity.load(new File(c.getCacheDir(),"lan-vpn236"));ConnectivityManager cm=(ConnectivityManager)c.getSystemService(Context.CONNECTIVITY_SERVICE);try(Socket before=new Socket()){before.connect(new InetSocketAddress(host,port),3000);check(before.isConnected(),"physical host endpoint reachable before fixture VPN");}
 shell("cmd appops set ru.truetv.probe ACTIVATE_VPN allow");shell("am start -n ru.truetv.probe/.VpnControl --ez bypass "+allowed);boolean vpn=false;long end=SystemClock.uptimeMillis()+10000;while(!vpn&&SystemClock.uptimeMillis()<end){Network n=cm.getActiveNetwork();NetworkCapabilities cap=n==null?null:cm.getNetworkCapabilities(n);vpn=cap!=null&&cap.hasTransport(NetworkCapabilities.TRANSPORT_VPN);Thread.sleep(50);}check(vpn,"own disposable VPN is active for phone UID");boolean blocked=false;long routing=SystemClock.uptimeMillis()+12000;while(!blocked&&SystemClock.uptimeMillis()<routing){try(Socket plain=new Socket()){plain.connect(new InetSocketAddress(host,port),750);}catch(IOException expected){blocked=true;}if(!blocked)Thread.sleep(200);}check(blocked,"default socket is blocked by black-hole VPN");
 LanNetwork.Route route=LanNetwork.route(c,host,"10.77.0.2,10.0.2.2");check(route.host.equals(host),"unrelated VPN address hint is ignored");if(!allowed){boolean refused=false;try{new Transfer.Sender().send(phone,route.host,port,pin,new Wire.Offer("VM phone",Collections.singletonList(new Wire.Item("blocked.bin","application/octet-stream",1))),n->new ByteArrayInputStream(new byte[]{1}),new Transfer.ClientEvents(){public void waiting(String n,String f,String v){}public void accepted(String f){}public void update(int n,String v,long b,long t){}},route.sockets);}catch(IOException policy){refused=true;log.append("POLICY ").append(policy.getClass().getSimpleName()).append('\n');}check(refused,"blocked VPN remains enforced with default-route fallback; no false success");}else for(int i=0;i<3;i++){byte[] payload=("lan-vpn-"+i).getBytes("UTF-8");List<String> names=new Transfer.Sender().send(phone,route.host,port,pin,new Wire.Offer("VM phone",Collections.singletonList(new Wire.Item("vpn-"+i+".bin","application/octet-stream",payload.length))),n->new ByteArrayInputStream(payload),new Transfer.ClientEvents(){public void waiting(String n,String f,String v){}public void accepted(String f){}public void update(int n,String v,long b,long t){}},route.sockets);check(names.size()==1,"Network-bound mutual TLS transfer completes with VPN on: "+i);}
 result.putBoolean("passed",true);}catch(Throwable e){StringWriter w=new StringWriter();e.printStackTrace(new PrintWriter(w));log.append(w);result.putBoolean("passed",false);}finally{try{shell("am force-stop ru.truetv.probe");shell("cmd appops set ru.truetv.probe ACTIVATE_VPN default");}catch(Exception e){log.append("CLEANUP ").append(e);}}result.putString("report",log+"Checks="+checks);finish(result.getBoolean("passed")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}}
